data = json.loads(sys.stdin.read())
inner = json.loads(data['result'])['data']['experiments']

# Count TRAINING seeds only (not eval), v2, done (any conclusion)
cells = {}
for eid, exp in inner.items():
    if 'eval' in eid:
        continue
    status = exp.get('status', '')
    conclusion = exp.get('conclusion', '')
    name = eid.lower()

    # Only count completed experiments
    is_done = status == 'DONE' and conclusion in ('success', 'negative')
    is_running = status == 'RUNNING'

    cell = None
    if 'v2' in name:
        if 'detach_ln' in name or 'detach+ln' in name:
            cell = 'Detach+LN (OFF,LN)'
        elif 'detach_occ' in name or 'detach_bn' in name:
            cell = 'Detach OCC (OFF,BN)'
        elif 'full_occ_ln' in name:
            cell = 'Full OCC LN (ON,LN)'
        elif 'full_occ_bn' in name or ('full_occ' in name and 'ln' not in name):
            cell = 'Full OCC BN (ON,BN)'
        elif 'vanilla' in name:
            cell = 'Vanilla'

    if cell:
        if cell not in cells:
            cells[cell] = {'done': [], 'running': []}
        if is_done:
            seed = exp.get('spec', {}).get('seed', '?')
            cells[cell]['done'].append(f'{eid}(s{seed})')
        elif is_running:
            seed = exp.get('spec', {}).get('seed', '?')
            cells[cell]['running'].append(f'{eid}(s{seed})')

print('=== V2 TRAINING SEED COUNTS (excl eval) ===')
for cell in sorted(cells.keys()):
    d = cells[cell]
    print(f'{cell}: {len(d[\"done\"])} done + {len(d[\"running\"])} running')
    if d['done']:
        print(f'  done: {d[\"done\"]}')
    if d['running']:
        print(f'  running: {d[\"running\"]}')

# Also check for any detach experiments not caught
print()
print('=== ALL experiments with detach (any version) ===')
for eid in sorted(inner.keys()):
    if 'detach' in eid.lower() and 'eval' not in eid.lower():
